using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
using F = StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Algebra.Knot;

internal sealed class WeightedPathArtinRepresentationDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The actual weighted path matrices represent a finite Artin presentation and give a function on its algebraic Markov quotient.",
        H("Artin Representation and Signed Markov Descent"),
        Blocks(Describe.Lean(
            DescribeId.Create("weighted-path-artin-markov-invariant"),
            DeclarationHandle.Create("D5/S3/Quantum/Algebra/Knot/WeightedPathArtinRepresentation.weighted_path_artin_markov_invariant"),
            H("From literal path projections to the algebraic Markov quotient"),
            StatementSource.FromAuthor(Statement()),
            AssessedProvenance.FromRepo(),
            Blocks(
                Paragraph(Text("Let L be any finite decidable type, R any decidable symmetric relation, d strictly positive real vertex weights, and delta a strictly positive real number with the exact Perron equality at every vertex. Let A be a nonzero complex number satisfying delta = -A squared minus A inverse squared. The full endpoint block algebra C(R,n,s) and all empty path fibers are retained. No connectedness, weight symmetry, unit-circle condition or nonempty endpoint-fiber hypothesis is added.")),
                Paragraph(Text("Artin(n) is the actual PresentedGroup on Fin(n-1), with distant commutator relators and adjacent three-letter Artin relators. The zero and one strand presentations have empty generator types. The assignment rho(sigma_i) = A inverse times the identity plus A delta times P_(i+1) is constructed as a MonoidHom from Artin(n) to the units of C(R,n,s). Its explicit inverse is A times the identity plus A inverse delta times the same literal projection. Both adjacent Temperley-Lieb directions are consumed, including WeightedPathReverseTemperleyLieb; inverse and relator identities alone are helper calculations, not separately claimed mathematical breakthroughs.")),
                Paragraph(Text("The strandInclusion is a homomorphism between the actual presented groups, obtained by mapping each old generator to the slot with the same value and checking both relator families. The representation commutes with this inclusion and the actual path-append algebra homomorphism, using the existing projection naturality theorem. The exponent-sum homomorphism into Multiplicative integers descends through all relators. Its additive readout is writhe, with signed integer values.")),
                Paragraph(Text("PositiveBraid is the dependent sum of Artin(n) over natural n with n strictly positive. MarkovStep is defined independently of the trace: conjugation within a layer and each of the positive and negative last-generator stabilizations into the next layer. MarkovEquivalent is its equivalence closure. Define F(n,beta) = delta to the n-minus-one times (-A cubed) to the integer writhe of beta times tau(n,s)(rho(beta)). The theorem proves F agrees on every finite Markov equivalence chain. markovValue is an actual Quotient.lift to the algebraic Markov quotient, using that theorem.")),
                Paragraph(Text("For this crossing convention, the normalized tau stabilization coefficients are -A inverse cubed divided by delta for the positive generator, and -A cubed divided by delta for the negative generator. The positive move increments writhe by one and the negative move decrements it by one. In both cases the delta factor and integer writhe factor cancel the trace coefficient. The positive strand restriction is explicit; natural-number subtraction is not used to hide a zero-level normalization exception.")),
                Paragraph(Text("This is classical Jones and Temperley-Lieb mathematics. Aharonov, Jones and Landau, arXiv:quant-ph/0511096v2, Definition 2.5 and equation (4), use the crossing formula A E_i plus A inverse identity. The present E_i is delta times the literal projection. Their line-graph construction is not cited as an arbitrary-graph source theorem; the present actual binding reuses the repository's arbitrary finite Perron path results. Jones, A polynomial invariant for knots via von Neumann algebras, Bulletin of the AMS 12 (1985), pages 104-105, supplies the original trace and writhe construction. The reciprocal crossing convention A identity plus A inverse E_i would require the opposite writhe correction and is not mixed into this statement.")),
                Paragraph(Text("AlgebraicMarkovClass has not been identified with ambient-isotopy classes of oriented tame links. A geometric closure map, Alexander surjectivity, both directions of the geometric Markov theorem and a convention-preserving Jones identification are still required for that interpretation. This complex path-model result gives no Laurent integrality, finite-field specialization, prescribed polynomial realization or solution of Aiello-Baader-Ferretti Question 1 at p=3. Arbitrary positive Perron data also do not imply unitarity of this representation."))),
            DescribeRole.Theorem), OriginalMetricApplication())));

    private static DocumentBlock OriginalMetricApplication() =>
        new DocumentBlock.Section(H("The full original-metric kernel-reduction application"), Blocks(
        new DocumentBlock.Section(H("The original metric and its zero-response directions"), Blocks(
        Paragraph(Text("The mathematical application concerns the finite real operator class specified in continuation XIII, sections 1 through 5. A configuration is an independent subset of the nine original sites 1 through 9. The bits outside those sites are b(-1)=1, b(0)=0, b(10)=0, b(11)=1 and b(12)=0. An edge retains its center address and connects exactly two legal configurations differing by that single occupied site, with both adjacent bits zero. Each occupied site of a nonempty configuration gives one deletion edge, counted at its occupied endpoint. Both directed transports belong to that same edge.")),
        Paragraph(Text("The original class has a finite common real fiber dimension d, a fixed positive definite metric at each configuration, fixed responses L(q), and edge transports T(q,t) whose reverse is both the inverse and the adjoint for that original metric. The full direct sum carries the orthogonal sum of those metrics. The unique specified ready is r={3,7}; its fixed preparation u is a unit vector, and the trace of L(r) adjoint times L(r) on the entire original fiber is 2. No normalization by d or restriction of the trace to a response support is allowed. The same data are used for every input and every word.")),
        Paragraph(Text("The parameters are x=(sqrt(5)-1)/2, c=x sqrt(x), and alpha=3 pi/5. Thus x is strictly positive, x+x squared=1 and c squared=x cubed. For each original address j from 0 through 10, an active flip pair ordered by central bit 0,1 has scalar matrix [x,c;c,x squared], with its off-diagonal scalars multiplying the prescribed directed transports. A blocked internal singleton has coefficient b(j-1)b(j+1). The two boundary coefficients are b(1) at address 0 and b(9) at address 10. Every other matrix entry is zero. These formulas apply on legal configurations alone.")),
        Paragraph(Text("The original generator is strictly left weighted: A(j)=alpha L (I+B(j)); the original call is its actual matrix exponential U(j)=exp(A(j)). The original class requires all eleven equations U(j) to the tenth power=I, all ten adjacent Artin equations, and all forty-five distant equations on the whole carrier. It does not assume endpoint isometry, ready injectivity, cyclicity, normality, a common active plane, response intertwining or continuous conservation. A chronological positive word (j1,...,jk) acts as U(jk)...U(j1); the empty word acts as I. There is no cutoff on word length.")))),

        new DocumentBlock.Section(H("An exact two-label path correspondence"), Blocks(
        Paragraph(Text("Use the finite label set {0,1} and the symmetric relation R(a,b) meaning that at least one of a,b is zero. The loop R(0,0) is essential and is permitted by WeightedLegalPathTemperleyLieb. Give labels 0 and 1 weights 1 and x, and set delta=1+x=x inverse. At label 0 the Perron sum is 1+x=delta. At label 1 it is 1=delta x. Both weights and delta are strictly positive, so all hypotheses of the frozen weighted-path supplier have their literal values.")),
        Paragraph(Text("The supplier carrier is LegalPath(R,12,1,1). Its coordinates k=0,...,12 are the bits b(k-1). The endpoint relations force coordinates 1 and 11 to be zero; coordinates 2 through 10 are exactly the nine original occupation bits. Extend an original configuration by those four fixed endpoint and adjacent-endpoint values to obtain a supplier path. Read positions 2 through 10 to recover the original configuration. These maps are inverse on every coordinate, and not merely on cardinalities. The final outer bit b(12)=0 remains fixed outside the length-12 path.")),
        Paragraph(Text("Supplier interior index i=j+1 corresponds to original address j, including j=0 and j=10. Its matrix entry is zero unless the two paths agree away from i and their flanks coincide. For common flank 0, middle bits 0,0 give 1/delta=x; bits 1,1 give x/delta=x squared; mixed middle bits give sqrt(x)/delta=c. Common flank 1 forces middle bit 0 and gives 1/(delta x)=1. Unequal flanks give zero. At the left boundary, the common-flank condition is exactly b(1)=1; at the right it is exactly b(9)=1. Thus every active entry, blocked singleton, off-support zero, and boundary coefficient is the literal original coefficient after one common permutation of configuration labels.")),
        Paragraph(Text("The original number of configurations is the sum, for n=0 through 5, of binomial(10-n,n), equal to 89. Deletion edges are counted by the sum, for n=1 through 5, of n times binomial(10-n,n), equal to 235. The deletion representation retains the occupied endpoint and the deleted center; adding a direction bit gives 470 directed edges with a specified reversal. Eleven addresses, ten increasing adjacent pairs and forty-five increasing pairs separated by at least two are the actual relation domains. The chosen three-dimensional fibers give 267 original real coordinates. Cardinality equalities support these statements only together with the two-sided configuration and edge correspondences.")))),

        new DocumentBlock.Section(H("Baseline exponentials and the public representation"), Blocks(
        Paragraph(Text("For identity edge transports, write P(j) for the original real scalar coefficient matrix, and P(j)H for its action on the two active real coordinates. The weighted-path theorem gives the idempotence, original self-adjointness and forward adjacent law of these literal matrices; WeightedPathReverseTemperleyLieb supplies the reverse adjacent law. Reindexing uses the same configuration equivalence at every address. No privately proved matrix braid lemma is duplicated.")),
        Paragraph(Text("The public WeightedPathArtinRepresentation.representation can be evaluated at endpoint 1 of its full endpoint block algebra. Choose its crossing parameter A=exp(2 pi i/5). The parameter identity is delta=-A squared-A inverse squared. With zeta=exp(3 pi i/5), zeta=-A inverse. Substituting the parameter identity gives -A delta=zeta(zeta-1). Consequently the original phase matrix zeta[I+(zeta-1)P(j)] is minus the represented Artin generator. Adjacent and distant equations follow by mapping the actual PresentedGroup relators, evaluating the common endpoint block, applying the common configuration reindexing and multiplying both sides by the same scalar power. The scalar signs agree because the relation lengths are three and two respectively.")),
        Paragraph(Text("These represented matrices must additionally be identified with the actual baseline exponentials. Multiplication by i on the complex configuration space is J=[0,-1;1,0] on each original pair of real coordinates. Thus the realification of i alpha(I+P(j)) is C(j)=alpha JH(I+P(j)H). The identity and P(j) commute. The public BarrigaTenModeFourierEdgeRefutation.expIdempotent applies to this actual idempotent P(j); together with the exponential addition formula for commuting matrices, it gives exp(i alpha(I+P(j)))=zeta[I+(zeta-1)P(j)]. A continuous realification ring homomorphism and NormedSpace.map_exp then identify its realification with exp(C(j)), rather than postulating a desired Jones family.")),
        Paragraph(Text("Since zeta to the tenth power=1, the two projection eigenspaces have tenth powers 1 for their respective scalars zeta and zeta squared. This proves all eleven tenth-return equations, separately from the equal-length Artin arguments. Original Euclidean orthogonality follows from C(j) transpose=-C(j): P(j)H is symmetric, JH is skew symmetric, and they commute because P(j) acts only on configuration labels. Matrix.exp_transpose and the commuting exponential inverse identity give K(j) transpose times K(j)=I, where K(j)=exp(C(j)). No original isometry of the later sheared model follows from this calculation.")))),

        new DocumentBlock.Section(H("The complete three-dimensional model and the common similarity"), Blocks(
        Paragraph(Text("Choose V(q)=R cubed with its usual Euclidean metric for every original configuration, and T=I3 in both directions on every original edge. Let s={1,3,7}. It is joined to r by the original address-one edge, whose neighbors b(0),b(2) are zero. Set lambda(s)(a1,a2)=a1 and lambda(q)=0 at every other vertex. Define L(q)(a,z)=(Ja,lambda(q)(Ja)). In original coordinates L(r)=[0,-1,0;1,0,0;0,0,0] and L(s)=[0,-1,0;1,0,0;0,-1,0]. The original preparation remains (1,0,0) at r.")),
        Paragraph(Text("Reorder, without changing the metric, the 267 original coordinates as H plus Z, where H=(R squared) to the power E and Z=R to the power E. This is an explicit permutation of E times {0,1,2}; no coordinate is removed. Lambda maps a to the family lambda(q)(a(q)), and JH is the direct sum of J. The original unchanged B(j) is block diagonal with blocks P(j)H and P(j)Z. The original response has blocks [JH,0;Lambda JH,0]. Its strict-left generator therefore has blocks [C(j),0;Lambda C(j),0]. In particular the original right-hand block (I+P(j)Z) disappears because it is multiplied by a zero response column, not because Lambda commutes with P(j).")),
        Paragraph(Text("Define S(a,z)=(a,z+Lambda a) and S inverse(a,z)=(a,z-Lambda a). These are inverse maps on the same whole original carrier. Direct block multiplication gives A(j)=S diag(C(j),0) S inverse, with exactly this same S at all eleven original addresses. Matrix.exp_units_conj, together with the block-diagonal exponential identity, yields U(j)=S diag(K(j),I) S inverse=[K(j),0;Lambda(K(j)-I),I]. The original B(j) is still the matrix prescribed by its original coefficients and transports; it is not defined by this similarity.")),
        Paragraph(Text("For every finite chronological word, induction on the actual list cancels each intervening S inverse S. The result is U(w)=S diag(K(w),I) S inverse. The empty list gives I, since S S inverse=I. This argument applies without a length bound. It transfers the eleven tenth-return, ten adjacent and forty-five far equations to the actual U on the full 267-dimensional carrier. The same formula fixes (0,z) for every z in the complete 89-dimensional stationary space, including all combinations of original third directions.")),
        Paragraph(Text("Root calibration is checked in the original metric independently of similarity. Since r differs from s, lambda(r)=0. The full three-dimensional matrix L(r) transpose L(r) is diag(1,1,0), whose unnormalized full trace is 2; the specified preparation has squared norm 1. S restricts to the identity on the original ready fiber. No ready injectivity, active-plane premise or change of preparation has been inserted.")))),

        new DocumentBlock.Section(H("Kernel reduction for every original positive metric"), Blocks(
        Paragraph(Text("Let V be any finite-dimensional real inner-product space with its given positive metric g, and let F be any real endomorphism. Put Z=kernel F and W=Z orthogonal complement, with both complements and adjoints taken in that same g. Then kernel F=kernel F adjoint if and only if F(W) is contained in W. This includes zero-dimensional fibers, zero responses and nontrivial stationary directions; it assumes neither normality nor endpoint isometry.")),
        Paragraph(Text("For the forward direction, the finite-dimensional adjoint identity W=range F adjoint, applied to F adjoint, identifies range F with W when the two kernels agree. Hence F maps every input into W. Conversely, decompose each v as z+w with z in Z and w in W. Invariance and Fz=0 imply range F is contained in W. Rank-nullity gives dim(range F)=dim V-dim Z, while the orthogonal dimension identity gives dim W=dim V-dim Z. The containment is therefore equality. Taking original orthogonal complements and using (range F) orthogonal complement=kernel F adjoint gives Z=kernel F adjoint.")),
        Paragraph(Text("In original finite coordinates, write the given metric as a positive-definite real matrix G. Its pairing is exactly g(u,v)=u transpose G v, its squared norm is u transpose G u, and its adjoint of a matrix F is D=G inverse F transpose G. Positivity makes G invertible; multiplying gives GD=F transpose G. Thus g(u,Dv)=(Fu) transpose Gv=g(Fu,v), so uniqueness of the adjoint identifies this D with the preceding adjoint. W is precisely the set of v with z transpose Gv=0 for every z satisfying Fz=0. Applying the equivalence at each original q uses G=g(q) and F=L(q), and yields exactly source (1.9), including arbitrary original positive metrics. This construction expresses the metric already given; it introduces no shear, new metric, quotient or omitted direction.")),
        Paragraph(Text("The formal ingredients are LinearMap.orthogonal_ker, LinearMap.orthogonal_range, Submodule.exists_add_mem_mem_orthogonal, LinearMap.finrank_range_add_finrank_ker, Submodule.finrank_add_finrank_orthogonal, Submodule.eq_of_le_of_finrank_eq and Submodule.orthogonal_orthogonal. Matrix.PosDef supplies positivity and invertibility of the original G; InnerProductSpace.Core records its literal pairing, and LinearMap.eq_adjoint_iff supplies adjoint uniqueness. These standard finite-dimensional results are reused, with no separate kernel-reduction theorem or theorem handle added to the project.")))),

        new DocumentBlock.Section(H("Original kernels, adjoints and metric consequences"), Blocks(
        Paragraph(Text("At every original vertex, J is invertible, so L(q)(a,z)=0 is equivalent to a=0. Thus its kernel is exactly the third-coordinate line. Every identity transport maps that entire line onto the corresponding line at the opposite endpoint, in both directions on all 235 original edges. The original Euclidean adjoint at s is L(s) transpose(xi,eta,zeta)=(eta,-xi-zeta,0). Its kernel is exactly the line generated by (1,0,-1), which differs from the original kernel generated by (0,0,1). Specifically L(s)e3=0 but L(s) transpose e3=(0,-1,0).")),
        Paragraph(Text("The original orthogonal complement of the kernel is the coordinate plane z=0. It is not preserved at s, since L(s)e2=(-1,0,-1). The same original ready edge fails response intertwining: (L(s)T(s,r)-T(s,r)L(r))e2=-e3. These failures are compatible with exact kernel transport on that edge. More generally, in finite dimension equality of the kernel and adjoint kernel is equivalent to invariance of the original orthogonal complement under L, using range L=(kernel L adjoint) orthogonal complement and rank-nullity. This is a statement about the fixed original inner product, not about an arbitrary invariant complement.")),
        Paragraph(Text("Let a be the active vector supported at r with value (1,0), so v=(a,0) is the original ready preparation and Lambda a=0. For each real internal parameter h between 0 and 1, apply the projection exponential formula to C(1). Its active evolution is R(alpha h)(I-P(1)H)+R(2 alpha h)P(1)H, where R(theta)=exp(theta J). The original off-diagonal coefficient from r to s is c, hence the active value at s is c[R(2 alpha h)-R(alpha h)](1,0). The common-similarity formula for h A(1) gives a third-coordinate value c[cos(2 alpha h)-cos(alpha h)] at s and zero at all other third coordinates.")),
        Paragraph(Text("The active evolution is Euclidean orthogonal and has total squared norm 1. The original active and third coordinates are orthogonal in the original metric. Thus the full original squared norm is 1+c squared[cos(2 alpha h)-cos(alpha h)] squared. PentagonCosines and elementary angle transformations give cos(alpha)=-x/2 and cos(2 alpha)=-(1+x)/2. At h=1 the third coordinate is -c/2 and the squared norm is exactly 1+x cubed/4, strictly greater than 1. This is the legal original single-letter word (1), acting on the original fixed unit preparation, with no additional physical preparation or fractional call.")),
        Paragraph(Text("The model satisfies all original class premises and all edge kernel transport, but fails original kernel reduction at s. Thus both the implication from the original class to the conjunction of reduction and transport, and the implication from that class plus transport to reduction, are false. The one same-ready mass increase excludes original endpoint isometry U(1) adjoint U(1)=I and the original all-input, all-internal-time conservation implication. It does not infer a physically executable control from the mathematical parameter h. Every norm, transpose and orthogonal complement in this argument belongs to the same original Euclidean metric, with all three coordinates at every vertex retained.")))),

        new DocumentBlock.Section(H("The graph complement and the limits of downstream use"), Blocks(
        Paragraph(Text("The graph G of Lambda consists of (a,Lambda a), while Z consists of (0,z). Every vector has the unique decomposition (a,z)=(a,Lambda a)+(0,z-Lambda a). The graph is invariant under L and every U(j) by their actual block formulas. It gives an algebraic direct sum with Z, but not an original orthogonal direct sum. Taking a supported at s with value (1,0) gives original squared norms 1 for (a,0) and 2 for S(a,0). The graph vector (a,Lambda a) has nonzero original inner product with the third basis vector at s. Hence S is not an original isometry.")),
        Paragraph(Text("The original golden matrices need not preserve this graph. The original ready vector belongs to it because Lambda a=0. Yet B(1)(a,0)=(P(1)H a,0), while Lambda P(1)H a has value c at s. Since c is strictly positive, that output is not in the graph. This directly shows why similarity of call products does not license restricting the original B family to the graph. The original orthogonal active plane also fails invariance under U(1), by the explicitly nonzero third coordinate at the legal endpoint.")),
        Paragraph(Text("The nondegenerate-capacity and original-metric assembly consumers in XII49.2 and XII53.3 through 54.1, followed by IV210.1, keep their own full premises. XII49.1 begins with an arbitrary common finite real dimension and ready nondegeneracy, together with the full original class data. XII53.3 derives dimension two and the ready skew-complex response; only then does XII54.1 invoke its real two-dimensional consumers to furnish all-vertex skew adjoints, full-edge response intertwining, endpoint isometry, continuous conservation and configuration-preserving original isometric complex coordinates. Dimension two is a conclusion of that preceding capacity argument, rather than an extra assumption on XII49.1. A restriction to the original kernel orthogonal complement must first preserve the original responses, golden operators and transports. This example fails that response restriction at s and fails full-carrier original mass conservation. A graph, quotient or alternative invariant metric does not supply the missing original-metric premise.")),
        Paragraph(Text("The model has a nonzero ready kernel and d=3. It does not refute the conditional equivalence between ready cyclicity, ready nondegeneracy, d=2 and native structure asserted for the original XII consumer class with its own premises. The sphere-phase descent and Born consumers in XII62.1 and XII62.3 through 68 also retain ready nondegeneracy, ray dependence of local rates and the entire response and process contracts. This finite model supplies none of those omitted premises.")))),

        new DocumentBlock.Section(H("Unresolved universal questions and physical scope"), Blocks(
        Paragraph(Text("The universal implication from the original class to kernel transport alone remains unresolved here: this model satisfies transport on every edge and therefore does not refute it. The universal ready decomposition into an original orthogonal skew-complex two-plane and a zero kernel, without endpoint isometry and without ready nondegeneracy, also remains unresolved: this example happens to have that ready decomposition. Neither question is a proof or search target of this application. No classification of all capacities, arbitrary splittings or general quantum representations follows.")),
        Paragraph(Text("This is a finite conditional mathematical model. It does not implement the complete actual Omega, replace an infinite-dimensional CountRead common-cut response quotient by 267 dimensions, or supply the entire 610 source, vacuum interface or original fifteen-call reader. The original full target still includes all 89 configurations, all 235 edges, the 26+63 coordinate split, the unique ready, eleven pre-read and seven post-read permissions, two record cuts, 1024 terminals and 2048 formal joint labels. Those permissions and reporting structures are not additional positive-word operations.")),
        Paragraph(Text("Original sources, preparations, events, masses, references and copies, actual joints, units and scales, devices, controls and clocks must retain their common-source correspondence across every legal sequential, adaptive and parallel history and future. Fine-record tables, denominators, addresses, failure coordinates, output types, provenance, prefixes, occurrences and parent archives are not deleted, merged or moved forward. An archive does not grant simultaneous read comparison or reinsertion permission. Zero, no-path zero labels, failure, rejection, stop, alarm, destruction, leakage, return and reverse return remain separate; zero-mass branches receive no conditional state.")),
        Paragraph(Text("No Born/report law, positive-branch pure update, archive sufficiency, reader re-entry, complete path law, reference or joint positivity, actual complete positivity or instrument, physical preparation or acquisition of a clock is a conclusion here. Nor is there a claim of physical adoption, completed quantum origin from all sources, finite-sample certification, uniform error bounds, acquisition cost or reduced total independent information.")))),

        new DocumentBlock.Section(H("Sources and comparison boundaries"), Blocks(
        Paragraph(Text("The mathematical input is continuation XIII at source commit 3ed7a60989604fe721de14ed54eaae73153cf179. Its fixed XII, IV and V15 passages identify the intended source equations and consumer premises; their prose is not a Lean supplier. The exact formal suppliers are WeightedLegalPathTemperleyLieb, WeightedPathReverseTemperleyLieb, the public WeightedPathArtinRepresentation.representation, BarrigaTenModeFourierEdgeRefutation.expIdempotent, PentagonCosines, and pinned mathlib matrix, exponential, finite-group-presentation and Euclidean-space results. The application introduces no general Jones theorem, third-party admissible-tableau framework, or novelty and priority claim.")),
        Paragraph(Text("For the precise XII59.2 zero-extension comparison, choose its original isometries S(q)=I2. On each original three-dimensional fiber its response is [J,0;0,0], its metric is I3, both edge transports are I3, and its preparation is the same (1,0,0) at r. The original unchanged B(j) then gives generator diag(C(j),0) and actual exponential diag(K(j),I). The full trace is 2, and the eleven, ten and forty-five equations follow from this same baseline. Its original squared norm stays 1 on the same ready vector; its kernel equals its adjoint kernel at every vertex. The sheared model instead has the lower block Lambda(K(j)-I), which is responsible for the exact positive mass difference. This identification uses the displayed XII59.2 assignment; the additional XII59.1 equivalence between cyclicity, ready injectivity, d=2 and native structure retains all of its own hypotheses and is not asserted as a Lean supplier here.")),
        Paragraph(Text("The weaker XII14-16 comparison uses the specific six-layer assignment L(q)=D(cardinality q) with D(2)=J, D(1)=F(J;50/3,h12), D(3)=F(J;50/3,h23), D(0)=F(D(1);50/3,hN), D(4)=F(D(3);50/3,hN) and D(5)=F(D(4);50/3,hN). Here F is the matrix construction of XII14.2 with its positive-frequency and absolute trace-pairing admissibility conditions. Put a=1+x, d0=1+x squared and k=c squared. The prescribed h12,h23,hN are the exact values in XII(14.4), rather than free assumptions about endpoints. For each original active pair the actual strict-left unscaled generator is [aX,cX;cY,d0Y]. Its characteristic polynomial is z to the fourth +(a squared xi squared+d0 squared eta squared-k h)z squared+4 xi squared eta squared. Substitution gives roots plus or minus i(10/3), and plus or minus i10 for the pairs (1,2),(2,3), or plus or minus i(500/3) for (0,1),(3,4),(4,5). All four roots in each case are distinct. Their products with alpha are integer multiples 2 pi,6 pi or100 pi, so ordinary complex diagonalization gives the actual active exponential I4. These are the exact original hypotheses and conclusion of XII15.2; an exact Lean application must discharge the six actual F constructions and their polynomial-to-exponential step, rather than assume the displayed endpoint as a premise.")),
        Paragraph(Text("An annihilating polynomial suffices for this exponential calculation. For traceless two-by-two X and Y, direct multiplication gives YX=trace(XY)I-XY and (XY) squared=trace(XY)XY-xi squared eta squared I. Substitution into the actual four-by-four block gives C to the fourth +(a squared xi squared+d0 squared eta squared-k trace(XY))C squared+4 xi squared eta squared I=0. Complexification preserves this identity and the exponential. The polynomial factors into four distinct linear factors with the frequencies just specified. The pinned squarefree-annihilator semisimplicity theorem makes the eigenspaces span the entire complexified four-dimensional space. On each eigenvector the existing EnergyEigenstateStationarity exponential supplier acts by the scalar exponential; all four scalars are 1. Thus the exponential is the identity on every vector, and injectivity of complexification gives the original real identity. No endpoint equation is an input to this argument.")),
        Paragraph(Text("The active exponential is connected to the full original carrier by the coordinate embedding E of each ordered legal pair. The literal golden coefficients vanish outside that pair in both of its columns, and the response is diagonal in configuration labels. Therefore the full strict-left generator A and its actual four-dimensional active matrix C satisfy A E=E C. Induction gives A to the n times E=E times C to the n for every natural n, including zero. Applying the continuous left and right multiplication maps to the convergent exponential series gives exp(A) E=E exp(C). The active identity consequently fixes every vector in that original pair inside the full carrier. This verifies invariance and the restriction of the full exponential together; it does not infer an exponential restriction from a principal submatrix alone.")),
        Paragraph(Text("At address zero the full generator is diagonal in the original configuration decomposition, with fiber alpha(1+b(1))D(cardinality q). A continuous block-diagonal ring homomorphism carries the fiber exponentials into its full exponential. The negative-square identity follows from the same explicit basis S(X): X S(X)=S(X) xi J, so exp(tX)=S(X) exp(t xi J) S(X) inverse. The plane exponential is the realification of exp(i t xi), giving cos(t xi)I+sin(t xi)X/xi. On r the factor is alpha J; on s it is 2 alpha D(3), whose angle is 20 pi. Thus the zero endpoint and the active one endpoint are actual restrictions of the one fixed six-layer model with its original identity transports and Euclidean metrics. Multiplication of these full endpoints restricts to multiplication of their four-dimensional matrices because both intertwine the same embedding E.")),
        Paragraph(Text("For the same original pair r={3,7}, s={1,3,7}, XII15.2 gives U(1)=I4 on that whole pair. At address zero, b1(r)=0, D(2)=J, b1(s)=1 and D(3) squared=-(50/3) squared I. The negative-square exponential with alpha(50/3)=10 pi gives U(0)=diag(R(alpha),I2), where R(theta)=[cos(theta),-sin(theta);sin(theta),cos(theta)]. Both endpoints preserve this pair, so restricting their full-carrier products is lawful. The zero/one adjacent products restrict to diag(R(alpha) squared,I2) and diag(R(alpha),I2). Their first diagonal entries differ by cos(2 alpha)-cos(alpha)=-1/2. Consequently that specific weaker model fails an original adjacent equation and cannot replace the full-XIII model. The source-specific six-layer exponential identity is not furnished by the weighted-path representation or by a theory theorem name. No kernel verification of XII15.2, XII40.2, XII49.2, XII53.3-54.1, XII59.1 or XII62-68 is inferred here.")),
        Paragraph(Text("For source XIII5.1's literature correspondence, qJ=exp(2 pi i/5), kFLW=2, rFLW=5, n=12 and lambda=[6,6]. FLW section 2 requires rFLW at least kFLW+1 and admissible prefix row difference at most 3. Its quantum integer [2] is (1+sqrt(5))/2=delta. Its formula qJ I-(1+qJ)E(i), under the common original path correspondence E(i)=P(i-1), becomes zeta[I+(zeta-1)P(j)] after multiplication by gamma=zeta/qJ. Equal word lengths preserve adjacent and distant relations; the ten returns use the literal projection phase. This identifies the fixed literature convention, while the formal path supplier above directly constructs the same original coefficients without an assumed tableau family. No density, classification, physical adoption or global originality assertion is used."))))));

    private static Formula Call(string name, params Formula[] args) =>
        new Formula.Apply(Seq(Operatorname, Grp(F.Id(name))), [.. args]);
    private static Formula All(string x, Formula type, Formula body) =>
        new Formula.Bind(FormulaQuantifier.ForAll, FormulaIdentifier.Create(x), type, body);
    private static Formula EqTo(Formula x, Formula y) =>
        new Formula.Relation(x, FormulaRelationOperator.Equal, y);
    private static Formula Statement()
    {
        Formula r = F.Id("R"), d = F.Id("d"), delta = F.Id("delta"), a = F.Id("A");
        Formula s = F.Id("s"), b = F.Id("beta"), c = F.Id("gamma");
        Formula value(Formula x) => Call("F", r, d, delta, a, s, x);
        Formula equality = EqTo(value(b), value(c));
        Formula invariant = All("s", F.Id("L"),
            All("beta", Call("PositiveBraid"), All("gamma", Call("PositiveBraid"),
                Seq(Call("MarkovEquivalent", b, c), Rightarrow, Sp, equality))));
        return Disp(Seq(Begin, Grp(F.Id("gathered")),
            Call("FiniteDecidable", F.Id("L")), Semi, Sp,
            Call("SymmetricPositivePerronData", r, d, delta), RowBreak,
            Call("Nonzero", a), Semi, Sp,
            EqTo(delta, Seq(Minus, Call("Pow", a, D(2)), Minus,
                Call("Pow", Call("Inv", a), D(2)))), RowBreak,
            invariant, End, Grp(F.Id("gathered"))));
    }
